/**
 * Upanishads funnel: types, data access and SEO helpers. Server-safe and
 * client-safe (no fs): content is imported as JSON/TS modules.
 * Data: src/content/funnels/upanishads (generated by scripts/funnels/upanishads/build.py
 * plus hand-written editorial files). Brief: lp/funnels/BRIEF.md.
 */
import type { Metadata } from 'next'
import isha from '@/content/funnels/upanishads/texts/isha.json'
import mandukya from '@/content/funnels/upanishads/texts/mandukya.json'
import katha from '@/content/funnels/upanishads/texts/katha.json'
import passagesJson from '@/content/funnels/upanishads/passages.json'
import cardsJson from '@/content/funnels/upanishads/cards.json'
import type { Quote, QuoteView } from '@/lib/quotes-shared'
import { toView } from '@/lib/quotes-shared'
import type { Locale } from '@/lib/locale'
import { AUTHOR_LD, PUBLISHER_LD, SITE, abs, pageMeta } from '@/lib/seo'

export { SITE }
export const UPDATED = '2026-10-30'
export const DISCLOSURE_EN = 'Wisdom translation, edited by Ankur Shukla. Commentary AI-drafted, under human review.'

export type Speaker = 'n' | 'N' | 'Y' | 'V' | 'T' | 's'

export type TextVerse = {
  ref: string
  anchor: string
  sa: string
  iast: string
  en: string
  reviewed: boolean
  basis: string
  kb: string[]
  speaker?: string
  variants?: string[]
}

export type Invocation = { sa: string; iast: string; en: string; reviewed: boolean; basis: string; where: string }
export type TextData = { id: string; verses: TextVerse[]; invocation?: Invocation }

export type Passage = { key: string; text: string; ref: string; sa: string; iast: string; basis: string; kb: string[]; note?: string }

export type Card = {
  id: string
  source: string
  sourceName: { en: string; hi: string }
  speaker?: { en: string; hi: string }
  sanskritLine: string
  sanskritFull: string
  iast: string
  meaning: { en: string; hi: string }
  reviewed: boolean
}

export const TEXTS: Record<'isha' | 'mandukya' | 'katha', TextData> = {
  isha: isha as TextData,
  mandukya: mandukya as TextData,
  katha: katha as TextData,
}

export const PASSAGES = passagesJson as Record<string, Passage>
export const CARDS = cardsJson as Card[]

export function passage(key: string): Passage {
  const p = PASSAGES[key]
  if (!p) throw new Error(`upanishads: unknown passage ${key}`)
  return p
}

export function verseOf(text: keyof typeof TEXTS, ref: string): TextVerse {
  const v = TEXTS[text].verses.find((x) => x.ref === ref)
  if (!v) throw new Error(`upanishads: unknown verse ${text} ${ref}`)
  return v
}

export function card(id: string): Card {
  const c = CARDS.find((x) => x.id === id)
  if (!c) throw new Error(`upanishads: unknown card ${id}`)
  return c
}

/** A funnel card as a QuoteView for the shared QuoteCard (copy links back to `path`). */
export function cardView(id: string, locale: Locale, path: string): QuoteView {
  const c = card(id)
  const q: Quote = {
    id: c.id,
    source: 'upanishad',
    sourceName: c.sourceName,
    speaker: c.speaker,
    sanskritFull: c.sanskritFull,
    sanskritLine: c.sanskritLine,
    iast: c.iast,
    meaning: c.meaning,
    context: { en: '', hi: '' },
    moments: ['wisdom'],
    rank: 1,
  }
  return toView(q, locale, { path })
}

export const cardImage = (id: string, format: 'post' | 'status' = 'post', lang: Locale = 'en') =>
  `/api/quote-card/${encodeURIComponent(id)}?format=${format}&lang=${lang}&theme=paper`

/** Lowercase a to z, 0 to 9, hyphens, at most 40 characters. */
export const pageKey = (s: string) =>
  s
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 40)
    .replace(/-+$/g, '')

export const gitaHref = (c: number, v: number, locale: Locale = 'en') =>
  `${locale === 'hi' ? '/hi' : ''}/gita/chapter/${c}/verse/${v}`

/** A Sanskrit passage as padas: one row per line and per danda, the danda kept with its word. */
export const padas = (s: string): string[] =>
  s
    .split('\n')
    .flatMap((l) => l.split(/(?<=[।|])\s+(?=\S)/u))
    .map((l) => l.trim().replace(/\s+([।॥|]+)/gu, '\u00a0$1'))
    .filter(Boolean)

// ── SEO ─────────────────────────────────────────────────────────────────────

type MetaInput = {
  title: string
  description: string
  path: string
  locale?: Locale
  /** The other-language twin, if any. */
  twin?: string
  ogCard?: string
  index?: boolean
}

/**
 * pageMeta (lib/seo) plus what this funnel has always sent: a self hreflang when there is no twin,
 * the share card as the OG image with its size, and an explicit robots tag.
 */
export function upMeta({ title, description, path, locale = 'en', twin, ogCard, index = true }: MetaInput): Metadata {
  const url = abs(path)
  const pair = twin ? (locale === 'en' ? { en: path, hi: twin } : { en: twin, hi: path }) : undefined
  const image = ogCard ? { url: abs(cardImage(ogCard, 'post', locale)), width: 1080, height: 1350 } : { url: `${SITE}/og-image.webp`, width: 1200, height: 630 }
  const m = pageMeta({ title, description, path, locale, twin: pair, ogImage: image.url, index })
  return {
    ...m,
    alternates: pair ? m.alternates : { canonical: url, languages: { [locale]: url, 'x-default': url } },
    openGraph: { ...m.openGraph, images: [image] },
    robots: index ? { index: true, follow: true } : { index: false, follow: true },
  }
}

export function articleLd(o: { headline: string; description: string; path: string; citation: string; locale?: Locale; about?: string }) {
  return {
    '@context': 'https://schema.org',
    '@type': 'Article',
    headline: o.headline,
    description: o.description,
    inLanguage: o.locale === 'hi' ? 'hi-IN' : 'en',
    mainEntityOfPage: abs(o.path),
    datePublished: UPDATED,
    dateModified: UPDATED,
    author: AUTHOR_LD,
    publisher: PUBLISHER_LD,
    citation: o.citation,
    ...(o.about ? { about: o.about } : {}),
  }
}

export const SOURCES_NOTE_EN =
  'Sanskrit from the Wisdom corpus, read against the sanskritdocuments.org editions (and GRETIL where it has the text); where the two differ, the proofread edition is used and the difference is listed for review. English is Wisdom’s own, drafted from the Sanskrit with Shankara’s commentary (S. Sitarama Sastri’s public-domain English) and checked for tone against Swami Paramananda (1919).'
